using GameTranslator.Core;
namespace GameTranslator.Core.Tests;
public class ReadingAreaTests_Timing
{
 [Fact]public void TimingControlsAreIndependentOfCaptionAppearanceAndBounded(){var t=new ReadingTiming(60,24,16,100,100,true,200).Validate();Assert.Equal(60,t.CaptureFps);Assert.Equal(24,t.PreviewFps);Assert.Equal(16,t.AreaReadMs);Assert.Equal(100,t.SettleMs);Assert.Equal(100,t.GoneMs);Assert.Equal(200,t.MinimumDisplayMs);Assert.Equal(60,(t with{CaptureFps=500}).Validate().CaptureFps);Assert.Null(new ReadingTiming().AreaReadMs);}
 [Fact]public void RestoringPositionsKeepsIdentityAndUserFormatting(){var a=ReadingArea.Phone() with{Id="mine",Source=new(.2,.5,.3,.6),FontSize=40,Enabled=false,Appearance=new(Font:"cairo")};var restored=ReadingArea.Restore(a);Assert.Equal("mine",restored.Id);Assert.Equal(a.FontSize,restored.FontSize);Assert.False(restored.Enabled);Assert.Equal("cairo",restored.Appearance!.Font);Assert.Equal(ReadingArea.Phone().Source,restored.Source);}
 [Fact]public void DialogueRestoreUsesVerifiedViCoordinates(){var a=ReadingArea.Restore(new("dialogue","الحوار",ReadingAreaKind.Dialogue,new(),new()));Assert.Equal(new CropRegion(.8,.918,.1,.9),a.Source);Assert.Equal(new CropRegion(.585,.785,.1,.9),a.Output);}
 [Fact]public void MapCardIsIndependentFromPauseNavigation(){var a=ReadingArea.MapCard();Assert.Equal(ReadingAreaKind.MapCard,a.Kind);Assert.False(a.AutoDetect);Assert.True(a.Source.Bottom<a.Output.Top);}
 [Fact]public void NormalMenuAppearsBesideSourceWhileSettingsStayInTheirCells(){var f=Frame.Blank(400,200);var line=new TextLine("Game",new(.1,.2,.3,.3));var plain=SpatialText.Build(f,new([line]),ReadingAreaKind.Menu);Assert.Equal("menu",plain.Kind);Assert.True(plain.Cells[0].Box.Left>line.Box!.Value.Right);var settings=SpatialText.Build(f,new([new("SETTINGS",new(.1,.02,.4,.08)),line]),ReadingAreaKind.Menu);Assert.Equal("settings",settings.Kind);Assert.True(settings.Cells[1].Box.Left<line.Box.Value.Left);}
 [Fact]public void PhonePresentationContainsNoBezelOrSceneImage(){var f=Frame.Blank(300,600);var p=SpatialText.Build(f,new([new("Jason",new(.2,.03,.8,.08)),new("Almost there",new(.1,.2,.8,.25))]),ReadingAreaKind.Phone);Assert.Null(SpatialText.WithImage(f,p).Image);Assert.Equal(2,p.Cells.Count);}
 [Fact]public void SourceGoneTimeCanBeChangedWithoutResettingTheStabilizer(){long now=0;var s=new SubtitleStabilizer(clock:()=>now){MissingTextMs=100};s.Feed("A complete sentence.");now=20;s.Feed("A complete sentence.");now=30;s.Feed("");now=129;Assert.Equal(StabilizerKind.None,s.Feed("").Kind);now=131;Assert.Equal(StabilizerKind.Clear,s.Feed("").Kind);}

 [Fact]public async Task OneMissingPhoneVisitDoesNotClearConversation(){long now=0;var f=Frame.Blank(300,600);for(int i=0;i<f.Pixels.Length;i+=4)f.Pixels[i]=f.Pixels[i+1]=f.Pixels[i+2]=235;using var session=new ReadingAreaSession([ReadingArea.Phone() with{Source=new(0,1,0,1)}],()=>new ChatReader(),new Engine(),()=>now);var shown=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);int clears=0;session.Caption+=c=>{if(c.Clear)clears++;else shown.TrySetResult();};await session.ProcessAsync(f);now=500;await session.ProcessAsync(f);await shown.Task.WaitAsync(TimeSpan.FromSeconds(3));now=2000;await session.ProcessAsync(Frame.Blank(300,600));Assert.Equal(0,clears);now=2500;await session.ProcessAsync(f);Assert.Equal(0,clears);now=4000;await session.ProcessAsync(Frame.Blank(300,600));now=5000;await session.ProcessAsync(Frame.Blank(300,600));Assert.Equal(1,clears);}
 [Fact]public async Task MissionDescriptionDoesNotNeedMapHeaderInsideCrop(){long now=0;using var session=new ReadingAreaSession([ReadingArea.MapCard()],()=>new Reader(),new Engine(),()=>now);var shown=new TaskCompletionSource<AreaCaption>(TaskCreationOptions.RunContinuationsAsynchronously);session.Caption+=c=>shown.TrySetResult(c);await session.ProcessAsync(Frame.Blank(600,400));now=500;await session.ProcessAsync(Frame.Blank(600,400));Assert.Contains("مهمة",(await shown.Task.WaitAsync(TimeSpan.FromSeconds(3))).Text);}
 private sealed class ChatReader:ITextReader{public string Read(Frame f)=>"Jason";public Reading ReadSpatial(Frame f)=>new([new("Jason",new(.35,.03,.65,.08)),new("Almost there!",new(.1,.2,.7,.25)),new("Are you home?",new(.3,.5,.85,.56))]);}
 private sealed class Reader:ITextReader{public string Read(Frame f)=>"Coming home, with Lucia out of prison.";public Reading ReadSpatial(Frame f)=>new([new(Read(f),new(.1,.2,.9,.4))]);}
 private sealed class Engine:ITextTranslator{public Task<string> TranslateAsync(string s,CancellationToken t=default)=>Task.FromResult("وصف مهمة واضح.");}
}
